import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  MessageSquare,
  Star,
  Brain,
  CheckCircle2,
  Trophy,
  RefreshCw,
  Code,
} from 'lucide-react';
import { getQuestionsForStack, generateAdvice } from '../data/interviewQuestions';

const STACKS = [
  { label: 'React JS', icon: '⚛️', value: 'react' },
  { label: 'Java / Spring Boot', icon: '☕', value: 'java' },
  { label: 'Flutter', icon: '🦋', value: 'flutter' },
  { label: 'Général', icon: '📋', value: 'general' },
];

function computeScore(answer, keywords) {
  const lower = answer.toLowerCase();
  let matched = 0;
  keywords.forEach((kw) => {
    if (lower.includes(kw.toLowerCase())) matched++;
  });
  return {
    matched,
    total: keywords.length,
    score: keywords.length > 0
      ? Math.round(((matched / keywords.length) * 4) * 10) / 10
      : 0,
    missing: keywords.filter(
      (kw) => !lower.includes(kw.toLowerCase()),
    ),
  };
}

export function InterviewSimulator() {
  const navigate = useNavigate();

  // Phase: 'select' | 'interview' | 'results'
  const [phase, setPhase] = useState('select');
  const [selectedStack, setSelectedStack] = useState(null);
  const [questions, setQuestions] = useState([]);
  const [currentQ, setCurrentQ] = useState(0);
  const [answer, setAnswer] = useState('');
  const [results, setResults] = useState([]);
  const [totalScore, setTotalScore] = useState(0);

  const handleSelectStack = (stack) => {
    const qs = getQuestionsForStack(stack);
    setSelectedStack(stack);
    setQuestions(qs);
    setCurrentQ(0);
    setAnswer('');
    setResults([]);
    setTotalScore(0);
    setPhase('interview');
  };

  const handleNext = () => {
    if (!answer.trim()) return;
    const q = questions[currentQ];
    const { score, missing } = computeScore(answer, q.keywords);
    const advice = generateAdvice(missing, q.category);
    const newResult = {
      question: q.q,
      category: q.category,
      answer: answer.trim(),
      score,
      advice,
    };
    const newResults = [...results, newResult];
    setResults(newResults);
    setAnswer('');

    if (currentQ < questions.length - 1) {
      setCurrentQ(currentQ + 1);
    } else {
      const total = newResults.reduce((acc, r) => acc + r.score, 0);
      setTotalScore(Math.round(total * 10) / 10);
      setPhase('results');
    }
  };

  const handleRestart = () => {
    setPhase('select');
    setSelectedStack(null);
    setQuestions([]);
    setCurrentQ(0);
    setAnswer('');
    setResults([]);
    setTotalScore(0);
  };

  const stackLabel =
    STACKS.find((s) => s.value === selectedStack)?.label ?? 'Questions générales';

  // ─── Stack selector screen ───────────────────────────────────────────────
  if (phase === 'select') {
    return (
      <div className="min-h-screen bg-sky-50 font-sans antialiased pb-20">
        <div className="bg-gradient-to-r from-sky-900 to-cyan-900 text-white py-6 px-4">
          <div className="max-w-3xl mx-auto flex items-center gap-4">
            <button
              onClick={() => navigate(-1)}
              className="p-2 bg-white/10 rounded-xl hover:bg-white/20 transition"
            >
              <ArrowLeft size={18} />
            </button>
            <h1 className="text-xl font-black">Simulateur d&apos;Entretien</h1>
          </div>
        </div>

        <div className="max-w-3xl mx-auto px-4 mt-8">
          <div className="bg-white rounded-2xl p-8 border border-sky-100 text-center">
            <div className="w-16 h-16 bg-cyan-50 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <Code size={32} className="text-cyan-500" />
            </div>
            <h2 className="text-2xl font-black text-sky-800 mb-2">
              Choisissez votre stack
            </h2>
            <p className="text-sm text-sky-500 mb-6">
              Sélectionnez la technologie pour laquelle vous souhaitez vous
              entraîner. Les questions sont adaptées à chaque stack.
            </p>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-lg mx-auto">
              {STACKS.map((s) => (
                <button
                  key={s.value}
                  onClick={() => handleSelectStack(s.value)}
                  className="p-5 bg-sky-50 rounded-2xl border-2 border-sky-100 hover:border-cyan-400 hover:bg-cyan-50 transition-all text-center group"
                >
                  <span className="text-3xl block mb-2">{s.icon}</span>
                  <span className="text-sm font-bold text-sky-700 group-hover:text-cyan-600 transition">
                    {s.label}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ─── Interview screen ────────────────────────────────────────────────────
  if (phase === 'interview') {
    const q = questions[currentQ];
    const progress = ((currentQ + 1) / questions.length) * 100;

    return (
      <div className="min-h-screen bg-sky-50 font-sans antialiased pb-20">
        <div className="bg-gradient-to-r from-sky-900 to-cyan-900 text-white py-6 px-4">
          <div className="max-w-3xl mx-auto flex items-center gap-4">
            <button
              onClick={handleRestart}
              className="p-2 bg-white/10 rounded-xl hover:bg-white/20 transition"
            >
              <ArrowLeft size={18} />
            </button>
            <div className="flex-1">
              <h1 className="text-xl font-black">Simulateur d&apos;Entretien</h1>
              <p className="text-sky-300 text-xs">
                {stackLabel} · Question {currentQ + 1}/{questions.length}
              </p>
            </div>
          </div>
          <div className="max-w-3xl mx-auto mt-4 space-y-1">
            <div className="h-1.5 bg-white/10 rounded-full overflow-hidden">
              <div
                className="h-full bg-cyan-400 rounded-full transition-all duration-500"
                style={{ width: `${progress}%` }}
              />
            </div>
            <div className="flex justify-between text-[10px] text-sky-300">
              <span>Progression</span>
              <span>
                {currentQ + 1}/{questions.length}
              </span>
            </div>
          </div>
        </div>

        <div className="max-w-3xl mx-auto px-4 mt-6 space-y-4">
          {/* Question card */}
          <div className="bg-white rounded-2xl p-6 border border-sky-100">
            <div className="flex items-start gap-3">
              <div className="p-3 bg-cyan-50 rounded-xl text-cyan-500 shrink-0">
                <MessageSquare size={24} />
              </div>
              <div className="min-w-0">
                <span className="inline-block text-[10px] font-black text-white bg-cyan-500 px-2 py-0.5 rounded-full uppercase mb-2">
                  {q.category}
                </span>
                <p className="text-lg font-bold text-sky-800 mt-1">{q.q}</p>
              </div>
            </div>
          </div>

          {/* Answer textarea */}
          <div className="bg-white rounded-2xl p-5 border border-sky-100">
            <textarea
              value={answer}
              onChange={(e) => setAnswer(e.target.value)}
              rows={5}
              className="w-full p-4 bg-sky-50 rounded-xl text-sm text-sky-800 outline-none border border-sky-100 resize-none focus:border-cyan-500 transition"
              placeholder="Rédigez votre réponse ici… Soyez précis et structuré."
            />
            <button
              onClick={handleNext}
              disabled={!answer.trim()}
              className="w-full mt-3 py-3.5 bg-cyan-500 text-white rounded-xl font-black text-sm hover:bg-cyan-600 transition-all disabled:bg-sky-100 disabled:text-sky-400"
            >
              {currentQ < questions.length - 1
                ? 'Question suivante'
                : 'Voir mes résultats'}
            </button>
          </div>

          {/* Tips card */}
          <div className="bg-white rounded-2xl p-4 border border-sky-100">
            <h3 className="text-xs font-black text-sky-800 uppercase mb-2 flex items-center gap-2">
              <Star size={14} className="text-cyan-500" /> Conseils
            </h3>
            <ul className="text-xs text-sky-600 space-y-1">
              <li>
                • Soyez précis et mentionnez les concepts techniques pertinents
              </li>
              <li>
                • Utilisez des mots-clés comme :{' '}
                {q.keywords.slice(0, 3).join(', ')}…
              </li>
              <li>
                • Structurez votre réponse clairement — 3 à 5 phrases
                idéalement
              </li>
            </ul>
          </div>
        </div>
      </div>
    );
  }

  // ─── Results screen ──────────────────────────────────────────────────────
  const getScoreColor = (s) =>
    s >= 16 ? 'text-teal-500' : s >= 10 ? 'text-cyan-500' : 'text-amber-500';
  const getScoreBg = (s) =>
    s >= 16 ? 'bg-teal-50 text-teal-600' : s >= 10 ? 'bg-cyan-50 text-cyan-600' : 'bg-amber-50 text-amber-600';

  return (
    <div className="min-h-screen bg-sky-50 font-sans antialiased pb-20">
      <div className="bg-gradient-to-r from-sky-900 to-cyan-900 text-white py-6 px-4">
        <div className="max-w-3xl mx-auto flex items-center gap-4">
          <button
            onClick={() => navigate(-1)}
            className="p-2 bg-white/10 rounded-xl hover:bg-white/20 transition"
          >
            <ArrowLeft size={18} />
          </button>
          <h1 className="text-xl font-black">Résultats de l&apos;Entretien</h1>
        </div>
      </div>

      <div className="max-w-3xl mx-auto px-4 mt-6 space-y-4">
        {/* Score hero */}
        <div className="bg-white rounded-2xl p-8 border border-sky-100 text-center">
          <Trophy
            size={56}
            className={`mx-auto mb-3 ${
              totalScore >= 16
                ? 'text-teal-500'
                : totalScore >= 10
                  ? 'text-cyan-500'
                  : 'text-amber-500'
            }`}
          />
          <div className="flex items-baseline justify-center gap-1">
            <span
              className={`text-5xl font-black ${getScoreColor(totalScore)}`}
            >
              {totalScore}
            </span>
            <span className="text-2xl font-black text-sky-300">/20</span>
          </div>
          <p className="text-sm text-sky-500 mt-1">
            Score global sur {questions.length} questions ·{' '}
            {totalScore >= 16
              ? 'Excellent !'
              : totalScore >= 10
                ? 'Bien, continuez à progresser.'
                : 'Encore des progrès à faire.'}
          </p>
          <button
            onClick={handleRestart}
            className="mt-5 px-6 py-3 bg-cyan-500 text-white rounded-xl font-black text-sm hover:bg-cyan-600 transition flex items-center gap-2 mx-auto"
          >
            <RefreshCw size={14} /> Recommencer
          </button>
        </div>

        {/* Per-question results */}
        {results.map((r, i) => (
          <div
            key={i}
            className="bg-white rounded-2xl p-5 border border-sky-100"
          >
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <span className="text-[10px] font-black text-white bg-sky-400 px-2 py-0.5 rounded-full uppercase">
                  {r.category}
                </span>
                <span className="text-[10px] font-bold text-sky-400">
                  Question {i + 1}
                </span>
              </div>
              <span
                className={`text-sm font-black px-2.5 py-0.5 rounded-full ${getScoreBg(
                  r.score,
                )}`}
              >
                {r.score}/4
              </span>
            </div>
            <p className="text-sm font-bold text-sky-800 mb-2">{r.question}</p>
            <p className="text-xs text-sky-500 bg-sky-50 p-3 rounded-xl italic mb-3">
              &ldquo;{r.answer}&rdquo;
            </p>

            {/* Advice row */}
            <div className="flex items-start gap-2 text-xs text-sky-700 bg-cyan-50 p-3 rounded-xl">
              <Brain size={14} className="text-cyan-500 shrink-0 mt-0.5" />
              <span>{r.advice}</span>
            </div>
          </div>
        ))}

        {/* Bottom CTA */}
        <div className="text-center pt-2">
          <button
            onClick={handleRestart}
            className="px-6 py-3 bg-cyan-500 text-white rounded-xl font-black text-sm hover:bg-cyan-600 transition inline-flex items-center gap-2"
          >
            <RefreshCw size={14} /> Recommencer un entretien
          </button>
        </div>
      </div>
    </div>
  );
}

