import { useEffect, useState } from 'react';
import { db, auth } from '../firebase/firebaseConfig';
import { collection, query, where, onSnapshot, doc, getDoc } from 'firebase/firestore';
import { getMissingSkills } from '../firebase/matchingEngine';
import { getResourcesForSkill } from '../data/interviewQuestions';
import {
  Target,
  BookOpen,
  Briefcase,
  Clock,
  CheckCircle2,
  XCircle,
  ExternalLink,
  TrendingUp,
  ChevronDown,
  ChevronUp,
  Lightbulb,
} from 'lucide-react';

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

const STATUS_CONFIG = {
  en_attente: { icon: Clock, label: 'En attente', classes: 'bg-amber-100 text-amber-700' },
  accepted: { icon: CheckCircle2, label: 'Acceptée', classes: 'bg-green-100 text-green-700' },
  rejected: { icon: XCircle, label: 'Refusée', classes: 'bg-red-100 text-red-700' },
};

function StatusBadge({ status }) {
  const cfg = STATUS_CONFIG[status] ?? STATUS_CONFIG.en_attente;
  const Icon = cfg.icon;
  return (
    <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-semibold ${cfg.classes}`}>
      <Icon size={14} />
      {cfg.label}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/*  Resource card                                                      */
/* ------------------------------------------------------------------ */

function ResourceCard({ skill }) {
  const resources = getResourcesForSkill(skill);
  const [open, setOpen] = useState(false);

  return (
    <div className="border border-sky-100 rounded-xl bg-white overflow-hidden transition-shadow hover:shadow-md">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="w-full flex items-center justify-between px-4 py-3 text-left"
      >
        <span className="flex items-center gap-2 text-sky-800 font-medium">
          <Lightbulb size={18} className="text-cyan-500" />
          {skill}
        </span>
        {open ? <ChevronUp size={18} className="text-sky-400" /> : <ChevronDown size={18} className="text-sky-400" />}
      </button>

      {open && (
        <div className="px-4 pb-4 space-y-2 border-t border-sky-50 pt-3">
          {resources.map((r, i) => (
            <a
              key={i}
              href={r.url}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center justify-between rounded-lg bg-sky-50 px-3 py-2 text-sm hover:bg-sky-100 transition-colors group"
            >
              <span className="text-sky-700 group-hover:text-sky-900">{r.title}</span>
              <span className="flex items-center gap-1">
                <span className="text-[10px] font-semibold uppercase tracking-wide text-cyan-600 bg-cyan-50 px-2 py-0.5 rounded-full">
                  {r.type}
                </span>
                <ExternalLink size={14} className="text-sky-400 group-hover:text-cyan-500" />
              </span>
            </a>
          ))}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Application row                                                    */
/* ------------------------------------------------------------------ */

function ApplicationRow({ application, candidateSkills }) {
  const [job, setJob] = useState(null);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    if (!application.jobId) return;
    const ref = doc(db, 'jobs', application.jobId);
    getDoc(ref).then((snap) => {
      if (snap.exists()) setJob({ id: snap.id, ...snap.data() });
    });
  }, [application.jobId]);

  if (!job) {
    return (
      <div className="flex items-center gap-3 px-4 py-3 animate-pulse">
        <div className="h-4 w-40 rounded bg-sky-100" />
        <div className="h-4 w-24 rounded bg-sky-100" />
      </div>
    );
  }

  const missingSkills = getMissingSkills(candidateSkills, job.profile ?? []);
  const matchedCount = (job.profile ?? []).length - missingSkills.length;
  const total = (job.profile ?? []).length || 1;
