export function CandidateDashboard() {
  const [profile, setProfile] = useState(null);
  const [applications, setApplications] = useState([]);
  const [jobsCache, setJobsCache] = useState({});
  const [loading, setLoading] = useState(true);

  /* ---- Load profile ---- */
  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) {
      setLoading(false);
      return;
    }

    getDoc(doc(db, 'users', uid)).then((snap) => {
      if (snap.exists()) setProfile({ id: snap.id, ...snap.data() });
      setLoading(false);
    });
  }, []);

  /* ---- Real-time applications + fetch jobs ---- */
  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;

    const q = query(collection(db, 'applications'), where('candidateId', '==', uid));
    const unsub = onSnapshot(q, (snapshot) => {
      const apps = [];
      const jobIds = new Set();

      snapshot.forEach((doc) => {
        const data = { id: doc.id, ...doc.data() };
        apps.push(data);
        if (data.jobId) jobIds.add(data.jobId);
      });

      setApplications(apps);

      // Eager-fetch jobs not yet cached
      const toFetch = [...jobIds].filter((id) => !jobsCache[id]);
      if (toFetch.length === 0) return;

      Promise.all(
        toFetch.map((id) =>
          getDoc(doc(db, 'jobs', id)).then((snap) => (snap.exists() ? { id, ...snap.data() } : null)),
        ),
      ).then((results) => {
        setJobsCache((prev) => {
          const next = { ...prev };
          results.forEach((r) => {
            if (r) next[r.id] = r;
          });
          return next;
        });
      });
    });

    return unsub;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ---- Derived data ---- */
  const candidateSkills = profile?.skills ?? [];

  // All unique missing skills across every application
  const allMissing = new Set();
  applications.forEach((app) => {
    const job = jobsCache[app.jobId];
    if (job) {
      getMissingSkills(candidateSkills, job.profile ?? []).forEach((s) => allMissing.add(s));
    }
  });
  const uniqueMissing = [...allMissing];

  /* ------------------------------------------------------------------ */
  /*  Render                                                             */
  /* ------------------------------------------------------------------ */

  if (loading) {
    return (
      <div className="min-h-screen bg-sky-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-3">
          <div className="h-10 w-10 animate-spin rounded-full border-4 border-sky-200 border-t-cyan-500" />
          <p className="text-sky-600 text-sm">Chargement du tableau de bord…</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-sky-50">
      {/* ---- Header ---- */}
      <header className="bg-gradient-to-r from-sky-900 to-cyan-900 px-6 py-8 sm:px-10">
        <div className="mx-auto max-w-6xl">
          <div className="flex items-center gap-3 text-white">
            <Target size={32} className="text-cyan-400" />
            <div>
              <h1 className="text-2xl font-bold tracking-tight">
                {profile?.fullName ? `Bon retour, ${profile.fullName.split(' ')[0]} 👋` : 'Tableau de Bord'}
              </h1>
              <p className="text-sm text-cyan-200/80 mt-0.5">
                {profile?.location ?? 'Localisation inconnue'} · {candidateSkills.length} compétences référencées
              </p>
            </div>
          </div>
        </div>
      </header>

      {/* ---- Body ---- */}
      <main className="mx-auto max-w-6xl px-4 sm:px-6 py-8 space-y-8">

        {/* ============ SKILL GAP — TO-DO ============ */}
        <section>
          <div className="flex items-center gap-2 mb-4">
            <Lightbulb size={22} className="text-cyan-500" />
            <h2 className="text-lg font-bold text-sky-800">Compétences à acquérir</h2>
            {uniqueMissing.length > 0 && (
              <span className="ml-auto text-xs font-semibold text-sky-500 bg-sky-100 px-3 py-1 rounded-full">
                {uniqueMissing.length} lacune{uniqueMissing.length > 1 ? 's' : ''}
              </span>
            )}
          </div>

          {uniqueMissing.length === 0 ? (
            <div className="rounded-2xl border border-sky-100 bg-white p-8 text-center">
              <CheckCircle2 size={48} className="mx-auto text-green-400 mb-3" />
              <p className="text-sky-700 font-medium">Aucune lacune détectée</p>
              <p className="text-sm text-sky-500 mt-1">
                Vous possédez déjà toutes les compétences requises par vos candidatures.
              </p>
            </div>
          ) : (
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {uniqueMissing.map((skill) => (
                <ResourceCard key={skill} skill={skill} />
              ))}
            </div>
          )}
        </section>

        {/* ============ APPLICATIONS TRACKER ============ */}
        <section>
          <div className="flex items-center gap-2 mb-4">
            <Briefcase size={22} className="text-cyan-500" />
            <h2 className="text-lg font-bold text-sky-800">Mes candidatures</h2>
            {applications.length > 0 && (
              <span className="ml-auto text-xs font-semibold text-sky-500 bg-sky-100 px-3 py-1 rounded-full">
                {applications.length} candidature{applications.length > 1 ? 's' : ''}
              </span>
            )}
          </div>

          {applications.length === 0 ? (
            <div className="rounded-2xl border border-sky-100 bg-white p-8 text-center">
              <Briefcase size={48} className="mx-auto text-sky-300 mb-3" />
              <p className="text-sky-700 font-medium">Aucune candidature pour le moment</p>
              <p className="text-sm text-sky-500 mt-1">
                Parcourez les offres et postulez pour voir vos candidatures apparaître ici.
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              {applications.map((app) => (
                <ApplicationRow key={app.id} application={app} candidateSkills={candidateSkills} />
              ))}
            </div>
          )}
        </section>

        {/* ============ RÉSUMÉ ============ */}
        <section>
          <div className="rounded-2xl border border-sky-100 bg-white p-5 flex flex-wrap items-center gap-6">
            <div className="flex items-center gap-2">
              <Briefcase size={18} className="text-cyan-500" />
              <span className="text-sm text-sky-600">
                <strong className="text-sky-800">{applications.length}</strong> candidature
                {applications.length > 1 ? 's' : ''}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <Lightbulb size={18} className="text-cyan-500" />
              <span className="text-sm text-sky-600">
                <strong className="text-sky-800">{uniqueMissing.length}</strong> compétence
                {uniqueMissing.length > 1 ? 's' : ''} à acquérir
              </span>
            </div>
            <div className="flex items-center gap-2">
              <BookOpen size={18} className="text-cyan-500" />
              <span className="text-sm text-sky-600">
                <strong className="text-sky-800">{candidateSkills.length}</strong> compétence
                {candidateSkills.length > 1 ? 's' : ''} référencée
                {candidateSkills.length > 1 ? 's' : ''}
              </span>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}

